// Regenerates TypeScript types from the OpenAPI contracts (never edit src/generated by hand).
//   node scripts/generate.mjs          → writes src/generated/*.ts
//   node scripts/generate.mjs --check  → exits 1 when the committed output is stale (for CI)
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import openapiTS, { astToString } from 'openapi-typescript';

const here = dirname(fileURLToPath(import.meta.url));
const contracts = resolve(here, '../../../../contracts/openapi');
const outDir = resolve(here, '../src/generated');
const SPECS = [
  ['gateway-bff.yaml', 'gateway-bff.ts'],
  ['gateway-bff-seller.yaml', 'gateway-bff-seller.ts'],
  ['search.yaml', 'search.ts'],
  ['catalog.yaml', 'catalog.ts']
];
const check = process.argv.includes('--check');
let stale = false;
mkdirSync(outDir, { recursive: true });
for (const [spec, out] of SPECS) {
  const src = resolve(contracts, spec);
  if (!existsSync(src)) {
    console.log(`skip ${spec} (not present yet)`);
    continue;
  }
  const ast = await openapiTS(pathToFileURL(src));
  const banner = `// GENERATED from contracts/openapi/${spec} by openapi-typescript — do not edit by hand.\n// Regenerate with: pnpm --filter @afrotransact/api-client generate\n/* eslint-disable */\n\n`;
  const text = banner + astToString(ast);
  const target = resolve(outDir, out);
  if (check) {
    const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
    if (current !== text) {
      console.error(`stale: src/generated/${out} — run pnpm --filter @afrotransact/api-client generate`);
      stale = true;
    }
  } else {
    writeFileSync(target, text);
    console.log(`wrote src/generated/${out}`);
  }
}
if (stale) process.exit(1);
